  describe('StudentDashboard: isTaskUnitTest', () => {
    it('should return false for empty or non-test tasks and steps', () => {
      expect(isTaskUnitTest(null, null)).toBe(false);
      expect(isTaskUnitTest(undefined, undefined)).toBe(false);
      expect(isTaskUnitTest({}, {})).toBe(false);
      expect(isTaskUnitTest(
        { start_lesson_name: '正負の数 計算演習', custom_unit_name: '通常授業' },
        { name: '演習問題1', fullTitle: '通常レッスン 演習問題1' }
      )).toBe(false);
    });

    it('should return false if yarinaoshi pattern is detected', () => {
      expect(isTaskUnitTest(
        { custom_unit_name: '単元テストーやり直しー' },
        { name: '単元テスト' }
      )).toBe(false);
      expect(isTaskUnitTest(
        { start_lesson_name: '単元確認テストーやり直しー' },
        { name: '第1章' }
      )).toBe(false);
      expect(isTaskUnitTest(
        { lesson_range: 'テストーやり直しー' },
        null
      )).toBe(false);
    });

    it('should identify unit tests from step', () => {
      expect(isTaskUnitTest(null, { name: '第1章 単元確認テスト' })).toBe(true);
      expect(isTaskUnitTest(null, { fullTitle: '一次方程式 単元テスト' })).toBe(true);
      expect(isTaskUnitTest(null, { name: '計算力 確認テスト' })).toBe(true);
      expect(isTaskUnitTest(null, { name: '単元再テスト' })).toBe(true);
      expect(isTaskUnitTest(null, { fullTitle: '英語 再テスト' })).toBe(true);
    });

    it('should identify unit tests from task fields', () => {
      expect(isTaskUnitTest({ start_lesson_name: '正負の数 単元テスト' })).toBe(true);
      expect(isTaskUnitTest({ end_lesson_name: '正負の数 単元確認テスト' })).toBe(true);
      expect(isTaskUnitTest({ lesson_range: '文字と式 確認テスト' })).toBe(true);
      expect(isTaskUnitTest({ custom_unit_name: '方程式 単元テスト' })).toBe(true);
      expect(isTaskUnitTest({ start_lesson_name: '再テスト対策' })).toBe(true);
      expect(isTaskUnitTest({ end_lesson_name: '数学 再テスト' })).toBe(true);
      expect(isTaskUnitTest({ lesson_range: '英語 再テスト' })).toBe(true);
      expect(isTaskUnitTest({ custom_unit_name: '国語 再テスト' }, null)).toBe(true);
    });
  });

