  describe('TeacherDashboard: isMatchingSubjectGroup, getGradeOrder, calcUnitMinOrderMap, extractRegularTestScoresFromReportCard', () => {
    it('should correctly match subjects in groups', () => {
      expect(isMatchingSubjectGroup('数学', '算数')).toBe(true);
      expect(isMatchingSubjectGroup('math', '数学')).toBe(true);
      expect(isMatchingSubjectGroup('英語', 'english')).toBe(true);
      expect(isMatchingSubjectGroup('理科', 'science')).toBe(true);
      expect(isMatchingSubjectGroup('社会', '歴史')).toBe(true);
      expect(isMatchingSubjectGroup('社会', '地理')).toBe(true);
      expect(isMatchingSubjectGroup('社会', '公民')).toBe(true);
      expect(isMatchingSubjectGroup('social', '社会')).toBe(true);
      expect(isMatchingSubjectGroup('国語', 'japanese')).toBe(true);
      expect(isMatchingSubjectGroup('音楽', '音楽')).toBe(true);
      expect(isMatchingSubjectGroup('数学', '英語')).toBe(false);
      expect(isMatchingSubjectGroup('', '数学')).toBe(false);
      expect(isMatchingSubjectGroup('数学', '')).toBe(false);
    });

    it('should correctly determine grade order', () => {
      expect(getGradeOrder('小1')).toBe(1);
      expect(getGradeOrder('1年生')).toBe(1);
      expect(getGradeOrder('小2')).toBe(2);
      expect(getGradeOrder('小3')).toBe(3);
      expect(getGradeOrder('小4')).toBe(4);
      expect(getGradeOrder('小5')).toBe(5);
      expect(getGradeOrder('小6')).toBe(6);
      expect(getGradeOrder('中1')).toBe(7);
      expect(getGradeOrder('7年生')).toBe(7);
      expect(getGradeOrder('中2')).toBe(8);
      expect(getGradeOrder('中3')).toBe(9);
      expect(getGradeOrder('高1')).toBe(10);
      expect(getGradeOrder('高2')).toBe(11);
      expect(getGradeOrder('高3')).toBe(12);
      expect(getGradeOrder(null)).toBe(99);
      expect(getGradeOrder('既卒')).toBe(99);
    });

    it('should correctly build unit minimum order map', () => {
      const items: any[] = [
        { grade: '小5', unit_name: '分数のたし算', sort_order: 50 },
        { grade: '小5', unit_name: '分数のたし算', sort_order: 52 },
        { grade: '小5', unit_name: '分数のひき算', sort_order: 60 }
      ];
      const map = calcUnitMinOrderMap(items);
      expect(map.get('小5_分数のたし算')).toBe(50);
      expect(map.get('小5_分数のひき算')).toBe(60);
    });

    it('should extract regular test scores from report card correctly', () => {
      const fullRes = {
        test_name: '1学期中間テスト',
        score_japanese: 85,
        score_math: 92,
        score_english: 78,
        score_social: 88,
        score_science: 90,
        score_total: 433,
        class_rank: '5位',
        school_rank: '12位',
        deviation_value: 62.5
      };
      const res = extractRegularTestScoresFromReportCard(fullRes);
      expect(res.testName).toBe('1学期中間テスト');
      expect(res.scoreJapanese).toBe('85');
      expect(res.scoreMath).toBe('92');
      expect(res.scoreEnglish).toBe('78');
      expect(res.scoreSocial).toBe('88');
      expect(res.scoreScience).toBe('90');
      expect(res.scoreTotal).toBe('433');
      expect(res.classRank).toBe('5位');
      expect(res.schoolRank).toBe('12位');
      expect(res.deviation).toBe('62.5');

      const emptyRes = extractRegularTestScoresFromReportCard({});
      expect(emptyRes.testName).toBeUndefined();
      expect(emptyRes.scoreJapanese).toBeUndefined();
      expect(emptyRes.scoreMath).toBeUndefined();
    });
  });

