  describe('TeacherDashboard: matchesMiniTestQuery & sortMiniTestResults', () => {
    it('matchesMiniTestQuery should match query against content, subject, passing line, and student name', () => {
      const item = { test_content: '単元確認テスト 計算', subject: '数学', passing_line: '80%以上' };
      expect(matchesMiniTestQuery(item, '佐藤 花子', '')).toBe(true);
      expect(matchesMiniTestQuery(item, '佐藤 花子', '  ')).toBe(true);
      expect(matchesMiniTestQuery(item, '佐藤 花子', '計算')).toBe(true);
      expect(matchesMiniTestQuery(item, '佐藤 花子', '数学')).toBe(true);
      expect(matchesMiniTestQuery(item, '佐藤 花子', '80%')).toBe(true);
      expect(matchesMiniTestQuery(item, '佐藤 花子', '佐藤')).toBe(true);
      expect(matchesMiniTestQuery(item, '佐藤 花子', '英語')).toBe(false);
    });

    it('sortMiniTestResults should sort by various criteria properly', () => {
      const mockStudents: any[] = [
        { id: 's1', name: '田中 太郎', name_kana: 'タナカ タロウ' },
        { id: 's2', name: '佐藤 一郎', name_kana: 'サトウ イチロウ' }
      ];

      const records: any[] = [
        { id: 'r1', date: getDynamicDateStr(-4), student_id: 's1', score: 85, passed: true, status: 'passed' },
        { id: 'r2', date: getDynamicDateStr(0), student_id: 's2', score: null, passed: false, status: 'unstarted' },
        { id: 'r3', date: getDynamicDateStr(-2), student_id: 's1', score: 50, passed: false, status: 'failed' }
      ];

      // date_asc
      const byDateAsc = sortMiniTestResults(records, 'date_asc', mockStudents);
      expect(byDateAsc.map(r => r.id)).toEqual(['r1', 'r3', 'r2']);

      // date_desc (default)
      const byDateDesc = sortMiniTestResults(records, 'default', mockStudents);
      expect(byDateDesc.map(r => r.id)).toEqual(['r2', 'r3', 'r1']);

      // name_asc
      const byNameAsc = sortMiniTestResults(records, 'name_asc', mockStudents);
      expect(byNameAsc[0].student_id).toBe('s2'); // 佐藤 comes before 田中

      // unsubmitted_first
      const byUnsubmitted = sortMiniTestResults(records, 'unsubmitted_first', mockStudents);
      expect(byUnsubmitted[0].id).toBe('r2');

      // passed_first
      const byPassed = sortMiniTestResults(records, 'passed_first', mockStudents);
      expect(byPassed[0].id).toBe('r1');
    });
  });

