  describe('TeacherDashboard: adjustTasksForStartUnits', () => {
    it('should skip unstarted tasks before start unit and reset skipped tasks after start unit', () => {
      const units: any[] = [
        { id: 'u1', subject: '数学', sequence_order: 1 },
        { id: 'u2', subject: '数学', sequence_order: 2 },
        { id: 'u3', subject: '数学', sequence_order: 3 },
        { id: 'u4', subject: '数学', sequence_order: 4 }
      ];

      const tasks: any[] = [
        { id: 't1', unit_id: 'u1', status: 'unstarted' },
        { id: 't2', unit_id: 'u2', status: 'completed' },
        { id: 't3', unit_id: 'u3', status: 'skipped' },
        { id: 't4', unit_id: 'u4', status: 'unstarted' },
        { id: 't5', unit_id: 'unknown', status: 'unstarted' }
      ];

      const startUnits = {
        math: units[2] // sequence_order: 3 is start unit
      };

      const adjusted = adjustTasksForStartUnits(tasks, units, startUnits);
      expect(adjusted[0].status).toBe('skipped');
      expect(adjusted[0].office_note).toBe('開始位置指定によりスキップ');
      expect(adjusted[1].status).toBe('completed'); // completed remains untouched
      expect(adjusted[2].status).toBe('unstarted'); // u3 >= 3, resets from skipped to unstarted
      expect(adjusted[2].office_note).toBe('');
      expect(adjusted[3].status).toBe('unstarted');
      expect(adjusted[4].status).toBe('unstarted');
    });
  });

