  describe('StudentDashboard: isStepSkipDisallowed', () => {
    it('should disallow skipping steps if preceding steps are incomplete', () => {
      const steps = [{ id: 'step-1' }, { id: 'step-2' }, { id: 'step-3' }];
      const completed = new Set(['step-1']);

      // Clicking step 1 (idx 0) when it's already complete or first incomplete -> allowed
      expect(isStepSkipDisallowed(0, steps, completed)).toBe(false);
      // Clicking step 2 (idx 1, first incomplete) -> allowed
      expect(isStepSkipDisallowed(1, steps, completed)).toBe(false);
      // Clicking step 3 (idx 2) when step 2 is incomplete -> disallowed
      expect(isStepSkipDisallowed(2, steps, completed)).toBe(true);

      // All completed -> allowed
      const allCompleted = new Set(['step-1', 'step-2', 'step-3']);
      expect(isStepSkipDisallowed(2, steps, allCompleted)).toBe(false);
    });
  });

  describe('StudentDashboard: resolveTaskStepCompletionStatus', () => {
    const today = getDynamicDateStr(0);

    it('should handle unit test statuses correctly without prematurely passing', () => {
      const failedTask: any = { status: 'failed', test_passed: false };
      const resFailed = resolveTaskStepCompletionStatus(failedTask, true, true, today);
      expect(resFailed.newStatus).toBe('failed');
      expect(resFailed.newTestPassed).toBe(false);

      const completedTask: any = { status: 'completed', test_passed: true };
      const resCompleted = resolveTaskStepCompletionStatus(completedTask, true, true, today);
      expect(resCompleted.newStatus).toBe('completed');
      expect(resCompleted.newTestPassed).toBe(true);

      const unstartedTask: any = { status: 'unstarted', test_passed: false };
      const resUnstarted = resolveTaskStepCompletionStatus(unstartedTask, true, true, today);
      expect(resUnstarted.newStatus).toBe('unstarted');
      expect(resUnstarted.newTestPassed).toBe(false);
    });

    it('should complete non-test task when all steps are completed', () => {
      const normalTask: any = { status: 'unstarted', test_passed: false };
      const res = resolveTaskStepCompletionStatus(normalTask, false, true, today);
      expect(res.newStatus).toBe('completed');
      expect(res.newTestPassed).toBe(true);
      expect(res.newActualCompletedDate).toBe(today);

      const resIncomplete = resolveTaskStepCompletionStatus(normalTask, false, false, today);
      expect(resIncomplete.newStatus).toBe('unstarted');
      expect(resIncomplete.newTestPassed).toBe(false);
    });
  });

