  describe('TeacherDashboard: buildDailyTaskFromTimetableConfig', () => {
    const mockStudent = {
      id: 'st-task-test',
      student_id: 'st-task-test',
      name: 'テスト生徒',
      grade: '中2',
      school_id: 'sch-1'
    } as any;
    const dynamicDate = getDynamicDateStr(2);

    it('should build unit task when unitId/startLessonId is provided with lesson_ids', () => {
      const config = {
        subject: '数学',
        unitId: 'unit-101',
        startLessonId: 'unit-101',
        endLessonId: 'unit-102',
        lesson_ids: ['101', '102']
      };
      const task = buildDailyTaskFromTimetableConfig({
        student: mockStudent,
        scheduleDate: dynamicDate,
        period: 1,
        config,
        targetUnitId: 'unit-101',
        commonOfficeNote: 'ノート連絡',
        curriculumMastersList: [],
        allCurriculumUnits: []
      });
      expect(task.student_id).toBe(mockStudent.id);
      expect(task.scheduled_date).toBe(dynamicDate);
      expect(task.period).toBe(1);
      expect(task.subject).toBe('数学');
      expect(task.lesson_ids).toEqual(['101', '102']);
      expect(task.office_note).toBe('ノート連絡');
      expect(task.status).toBe('unstarted');
    });

    it('should fallback extractedLessonIds to startLessonId if range resolves empty', () => {
      const config = {
        subject: '英語',
        unitId: 'unit-eng',
        startLessonId: 'unit-eng'
      };
      const task = buildDailyTaskFromTimetableConfig({
        student: mockStudent,
        scheduleDate: dynamicDate,
        period: 2,
        config,
        targetUnitId: 'unit-eng',
        curriculumMastersList: [],
        allCurriculumUnits: []
      });
      expect(task.subject).toBe('英語');
      expect(task.lesson_ids).toEqual(['unit-eng']);
    });

    it('should build custom theme task when unitId/startLessonId is missing', () => {
      const config = {
        subject: 'その他',
        customTheme: '面談指導',
        lesson_ids: ['custom-step-1']
      };
      const task = buildDailyTaskFromTimetableConfig({
        student: mockStudent,
        scheduleDate: dynamicDate,
        period: 3,
        config,
        targetUnitId: '',
        curriculumMastersList: [],
        allCurriculumUnits: []
      });
      expect(task.subject).toBe('その他');
      expect(task.custom_unit_name).toBe('面談指導');
      expect(task.lesson_ids).toEqual(['custom-step-1']);
    });

    it('should fallback custom theme task to customUnitId if lesson_ids is empty', () => {
      const config = {
        subject: '自由記述'
      };
      const task = buildDailyTaskFromTimetableConfig({
        student: mockStudent,
        scheduleDate: dynamicDate,
        period: 4,
        config,
        targetUnitId: '',
        curriculumMastersList: [],
        allCurriculumUnits: []
      });
      expect(task.subject).toBe('自由記述');
      expect(task.lesson_ids.length).toBe(1);
      expect(task.lesson_ids[0]).toContain(`custom-${mockStudent.id}-${dynamicDate}-4`);
    });
  });

  describe('TeacherDashboard: resolveCandidateUnitsFromPeriodSelections', () => {
    it('should return immediately if periodSelections is undefined or null', () => {
      const map = new Map<string, any>();
      resolveCandidateUnitsFromPeriodSelections(map, null, () => true);
      expect(map.size).toBe(0);
      resolveCandidateUnitsFromPeriodSelections(map, undefined, () => true);
      expect(map.size).toBe(0);
    });

    it('should add start and end lessons if matching subject and not unit test', () => {
      const map = new Map<string, any>();
      map.set('existing-1', { id: 'existing-1', name: '既存単元' });

      const selections = {
        1: { subject: '数学', startLessonId: 'm-1', startLessonName: '一次関数', endLessonId: 'm-2', endLessonName: '連立方程式' },
        2: { subject: '国語', startLessonId: 'j-1', startLessonName: '古文' },
        3: { subject: '数学', startLessonId: 'm-test', startLessonName: '単元確認テスト' }
      };

      resolveCandidateUnitsFromPeriodSelections(
        map,
        selections,
        (s) => s === '数学'
      );

      expect(map.has('m-1')).toBe(true);
      expect(map.get('m-1').name).toBe('一次関数');
      expect(map.has('m-2')).toBe(true);
      expect(map.get('m-2').name).toBe('連立方程式');
      // 国語はマッチしないので入らない
      expect(map.has('j-1')).toBe(false);
      // 単元確認テストは除外される
      expect(map.has('m-test')).toBe(false);
      // 既存単元は保持される
      expect(map.get('existing-1').name).toBe('既存単元');
    });
  });

  describe('TeacherDashboard: lookupLessonById', () => {
    const rawMasters = [
      { id: 'master-1', lesson_name: '正負の数1', unit_name: '正負の数', sort_order: 10, subject: '数学' },
      { id: 'master-2', lesson_name: '英語文法1', unit_name: null, sort_order: 20, subject: '英語' },
      { id: 'master-3', lesson_name: '30-歴史の概要', unit_name: '中1歴史', sort_order: 30, subject: '社会' }
    ];
    const curriculumUnits = [
      { id: 'unit-school-1', name: '学校独自単元', sequence_order: 5, subject: '理科' }
    ];

    it('should return null if id is empty or null', () => {
      expect(lookupLessonById('', rawMasters, curriculumUnits)).toBeNull();
      expect(lookupLessonById(null as any, rawMasters, curriculumUnits)).toBeNull();
    });

    it('should match master by id, sort_order, or lesson_name', () => {
      expect(lookupLessonById('master-1', rawMasters, curriculumUnits)?.id).toBe('master-1');
      expect(lookupLessonById('10', rawMasters, curriculumUnits)?.id).toBe('master-1');
      expect(lookupLessonById('英語文法1', rawMasters, curriculumUnits)?.id).toBe('master-2');
      expect(lookupLessonById('中1歴史 - 歴史の概要', rawMasters, curriculumUnits)?.id).toBe('master-3');
    });

    it('should fallback to curriculumUnits by id or name', () => {
      expect(lookupLessonById('unit-school-1', rawMasters, curriculumUnits)?.name).toBe('学校独自単元');
      expect(lookupLessonById('学校独自単元', rawMasters, curriculumUnits)?.id).toBe('unit-school-1');
    });

    it('should return null when no item matches', () => {
      expect(lookupLessonById('unknown-id-999', rawMasters, curriculumUnits)).toBeNull();
    });
  });

  describe('TeacherDashboard: sortCurriculumMasterUnits & calcUnitMinOrderMap edge cases', () => {
    it('should handle null/undefined grades, unit_names, and sort_orders gracefully', () => {
      const items = [
        { grade: null, unit_name: null, sort_order: null },
        { grade: undefined, unit_name: undefined, sort_order: undefined },
        { grade: '中1', unit_name: '正負の数', sort_order: 5 },
        { grade: '中1', unit_name: '正負の数', sort_order: 1 },
        { grade: '中1', unit_name: '文字と式', sort_order: 10 }
      ];
      const minMap = calcUnitMinOrderMap(items);
      expect(minMap.get('_')).toBe(0);
      expect(minMap.get('中1_正負の数')).toBe(1);

      const sorted = sortCurriculumMasterUnits(items);
      expect(sorted.length).toBe(5);
      // 中1 items should precede unassigned items (order 99)
      expect(sorted[0].grade).toBe('中1');
    });

    it('should sort items within same grade by unit min sort order then unit_name then sort_order', () => {
      const items = [
        { grade: '中2', unit_name: 'B単元', sort_order: 10 },
        { grade: '中2', unit_name: 'A単元', sort_order: 10 },
        { grade: '中2', unit_name: 'A単元', sort_order: 2 }
      ];
      const sorted = sortCurriculumMasterUnits(items);
      expect(sorted[0].unit_name).toBe('A単元');
      expect(sorted[0].sort_order).toBe(2);
      expect(sorted[1].unit_name).toBe('A単元');
      expect(sorted[1].sort_order).toBe(10);
      expect(sorted[2].unit_name).toBe('B単元');
    });
  });

