  describe('TeacherDashboard: adjustTasksForStartUnits edge cases', () => {
    const startUnits = {
      math: { sequence_order: 10 },
      english: { sequence_order: 20 },
      science: { sequence_order: 30 },
      social: { sequence_order: 40 },
      japanese: { sequence_order: 50 }
    } as any;

    it('should properly adjust tasks for english, social, and japanese start units', () => {
      const tasks = [
        { id: 't-eng', unit_id: 'u-eng', status: 'unstarted' },
        { id: 't-soc', unit_id: 'u-soc', status: 'skipped' },
        { id: 't-jpn', unit_id: 'u-jpn', status: 'unstarted' }
      ] as any;
      const units = [
        { id: 'u-eng', subject: '英語', sequence_order: 15 }, // < 20 -> skip
        { id: 'u-soc', subject: '社会', sequence_order: 45 }, // >= 40 -> unstart
        { id: 'u-jpn', subject: '国語', sequence_order: 60 }  // >= 50 -> unstarted
      ] as any;

      const adjusted = adjustTasksForStartUnits(tasks, units, startUnits);

      expect(adjusted[0].status).toBe('skipped');
      expect(adjusted[1].status).toBe('unstarted');
      expect(adjusted[2].status).toBe('unstarted');
    });
  });

