  describe('TeacherDashboard: adjustTasksForStartUnits across all subjects', () => {
    it('should adjust tasks for math, english, science, social, and japanese start units', () => {
      const schoolUnits = [
        { id: 'u-m1', subject: '数学', sequence_order: 1, name: '計算1' },
        { id: 'u-m2', subject: '数学', sequence_order: 2, name: '計算2' },
        { id: 'u-e1', subject: '英語', sequence_order: 1, name: '文法1' },
        { id: 'u-e2', subject: '英語', sequence_order: 2, name: '文法2' },
        { id: 'u-s1', subject: '理科', sequence_order: 1, name: '光1' },
        { id: 'u-s2', subject: '理科', sequence_order: 2, name: '光2' },
        { id: 'u-so1', subject: '社会', sequence_order: 1, name: '地理1' },
        { id: 'u-so2', subject: '社会', sequence_order: 2, name: '地理2' },
        { id: 'u-j1', subject: '国語', sequence_order: 1, name: '漢字1' },
        { id: 'u-j2', subject: '国語', sequence_order: 2, name: '漢字2' },
        { id: 'u-other', subject: '情報', sequence_order: 1, name: '情報1' }
      ] as any;

      const tasks = [
        { id: 't-m1', unit_id: 'u-m1', status: 'unstarted' },
        { id: 't-m2', unit_id: 'u-m2', status: 'skipped' },
        { id: 't-m3-done', unit_id: 'u-m2', status: 'completed' },
        { id: 't-e1', unit_id: 'u-e1', status: 'unstarted' },
        { id: 't-s1', unit_id: 'u-s1', status: 'unstarted' },
        { id: 't-so1', unit_id: 'u-so1', status: 'unstarted' },
        { id: 't-j1', unit_id: 'u-j1', status: 'unstarted' },
        { id: 't-other', unit_id: 'u-other', status: 'unstarted' },
        { id: 't-unknown', unit_id: 'u-unknown', status: 'unstarted' }
      ] as any;

      const startUnitsBySubject = {
        math: { sequence_order: 2 },
        english: { sequence_order: 2 },
        science: { sequence_order: 2 },
        social: { sequence_order: 2 },
        japanese: { sequence_order: 2 }
      } as any;

      const adjusted = adjustTasksForStartUnits(tasks, schoolUnits, startUnitsBySubject);

      // t-other has subject without startUnit -> stays unstarted
      expect(adjusted.find(t => t.id === 't-other')?.status).toBe('unstarted');
      // t-m3-done was completed and at sequence 2 -> stays completed
      expect(adjusted.find(t => t.id === 't-m3-done')?.status).toBe('completed');

      // t-m1 is before startUnit sequence_order 2 -> skipped
      const tm1 = adjusted.find(t => t.id === 't-m1');
      expect(tm1?.status).toBe('skipped');

      // t-m2 is at startUnit sequence_order 2 and was skipped -> unstarted
      const tm2 = adjusted.find(t => t.id === 't-m2');
      expect(tm2?.status).toBe('unstarted');

      // english, science, social, japanese should be skipped
      expect(adjusted.find(t => t.id === 't-e1')?.status).toBe('skipped');
      expect(adjusted.find(t => t.id === 't-s1')?.status).toBe('skipped');
      expect(adjusted.find(t => t.id === 't-so1')?.status).toBe('skipped');
      expect(adjusted.find(t => t.id === 't-j1')?.status).toBe('skipped');

      // unknown unit task is returned untouched
      expect(adjusted.find(t => t.id === 't-unknown')?.status).toBe('unstarted');
    });
  });

