      expect(resolveAdvanceTitle({ unit_name: '二次方程式', lesson_name: '' })).toBe('二次方程式');
      expect(resolveAdvanceTitle({ unit_name: '', lesson_name: '方程式の解き方' })).toBe('方程式の解き方');
      expect(resolveAdvanceTitle({ unit_name: '', lesson_name: '' })).toBe('新単元先取り学習');
