  describe('scheduler.ts: getLatestUnitTestStatusForSubject deep branch coverage', () => {
    it('should evaluate passed, failed, review, and override cases with unit name sanitization', () => {
      const today = getDynamicDateStr(0);
      const yesterday = getDynamicDateStr(-1);

      const miniResults = [
        // 1. passed unit test with subject prefix in unit_name and test_content
        {
          id: 'mt-p1',
          student_id: 'st-deep-1',
          subject: '数学',
          test_type: 'unit_test',
          unit_name: '数学: 一次関数',
          test_content: '数学: 一次関数のグラフ 単元確認テスト',
          score: 85,
          passed: true,
          passing_line: '80点以上',
          date: yesterday
        },
        // 2. review / check test (should not mark entire unit as completed)
        {
          id: 'mt-check',
          student_id: 'st-deep-1',
          subject: '数学',
          test_type: 'check_test',
          unit_name: '一次関数 まとめテスト',
          test_content: '一次関数 Check Test 1',
          score: 90,
          passed: true,
          date: yesterday
        },
        // 3. newer failed test on another unit -> should register as failedUnitTest and remove from completed keys
        {
          id: 'mt-fail1',
          student_id: 'st-deep-1',
          subject: '数学',
          test_type: 'unit_test',
          unit_name: '二次方程式',
          test_content: '二次方程式の解 単元テスト',
          score: 55,
          passed: false,
          passing_line: '75点',
          date: today
        }
      ] as any;

      const status = getLatestUnitTestStatusForSubject({
        studentId: 'st-deep-1',
        subject: '数学',
        miniTestResults: miniResults
      });

      expect(status.hasFailedUnitTest).toBe(true);
      expect(status.failedUnitTest?.id).toBe('mt-fail1');
      expect(status.completedUnitTestKeys.has('一次関数のグラフ 単元確認テスト')).toBe(true);
      // failed unit key should NOT be in completed keys
      expect(status.completedUnitKeys?.has('二次方程式')).toBe(false);
    });

    it('should handle evaluation overrides when previous entry had no score or eval', () => {
      const miniResults = [
        // older entry with score 90
        {
          id: 'mt-eval-1',
          student_id: 'st-eval',
          subject: '英語',
          test_type: 'unit_test',
          unit_name: '過去形',
          test_content: '過去形 - 単元テスト',
          score: 90,
          passed: true,
          date: getDynamicDateStr(-2)
        },
        // newer entry with no score (unsubmitted)
        {
          id: 'mt-eval-2',
          student_id: 'st-eval',
          subject: '英語',
          test_type: 'unit_test',
          unit_name: '過去形',
          test_content: '過去形 - 単元テスト',
          score: null,
          passed: undefined,
          date: getDynamicDateStr(-1)
        }
      ] as any;

      const status = getLatestUnitTestStatusForSubject({
        studentId: 'st-eval',
        subject: '英語',
        miniTestResults: miniResults
      });

      // The entry with evaluation should take priority over unsubmitted
      expect(status.completedUnitTestKeys.has('過去形')).toBe(true);
      expect(status.hasFailedUnitTest).toBe(false);
    });
  });

  describe('TeacherDashboard: resolveCandidateUnitsFromPeriodSelections & lookupLessonById', () => {
    it('should resolve candidate units from period selections including start and end lessons', () => {
      const combinedMap = new Map<string, any>();
      const periodSelections = {
        '1': {
          subject: '数学',
          startLessonId: 'lesson-s1',
          startLessonName: '式の計算 1',
          endLessonId: 'lesson-e1',
          endLessonName: '式の計算 2'
        },
        '2': {
          subject: '英語', // different subject
          startLessonId: 'eng-s1',
          startLessonName: 'Unit 1'
        },
        '3': {
          subject: '数学',
          startLessonId: 'lesson-ut',
          startLessonName: '式の計算 単元確認テスト' // unit test -> skipped
        }
      };

      const matchSubject = (s?: string) => s === '数学';
      resolveCandidateUnitsFromPeriodSelections(combinedMap, periodSelections, matchSubject);

      expect(combinedMap.has('lesson-s1')).toBe(true);
      expect(combinedMap.has('lesson-e1')).toBe(true);
      expect(combinedMap.has('eng-s1')).toBe(false);
      expect(combinedMap.has('lesson-ut')).toBe(false);

      // null periodSelections should be no-op
      resolveCandidateUnitsFromPeriodSelections(combinedMap, null, matchSubject);
      expect(combinedMap.size).toBe(2);
    });

    it('should lookup lessons by id, sort_order, lesson_name, or unit_name', () => {
      const masters = [
        { id: 'm-lookup-1', sort_order: 10, unit_name: '方程式', lesson_name: '移項' },
        { id: 'm-lookup-2', sort_order: 20, unit_name: '方程式', lesson_name: '解法' }
      ] as any;

      const units = [
        { id: 'u-lookup-1', sequence_order: 1, name: '一次関数' }
      ] as any;

      // match by id
      const byId = lookupLessonById('m-lookup-1', masters, units);
      expect(byId?.name).toBe('方程式 - 移項');

      // match by sort_order
      const byOrder = lookupLessonById('20', masters, units);
      expect(byOrder?.name).toBe('方程式 - 解法');

      // match by lesson_name
      const byName = lookupLessonById('移項', masters, units);
      expect(byName?.name).toBe('方程式 - 移項');

      // match by curriculum unit id
      const byUnit = lookupLessonById('u-lookup-1', masters, units);
      expect(byUnit?.name).toBe('一次関数');

      // empty id
      expect(lookupLessonById('', masters, units)).toBeNull();
      // not found
      expect(lookupLessonById('unknown-id', masters, units)).toBeNull();
    });
  });

