  describe('TeacherDashboard: newly extracted pure helpers (resolveNextAttendanceDateForStudent, resolveAutoDrillHomeworkText, isUnitTestCompletedForStudent, sortGradeOptions, inferSelectedStartGrade, calculateStudentMilestoneSeq)', () => {
    it('should resolveNextAttendanceDateForStudent correctly across all fallback chains', () => {
      const today = getDynamicDateStr(0);
      expect(resolveNextAttendanceDateForStudent(today, null)).toBe(today);

      const studentNoDays: Partial<Student> = { id: 's-nodays', selected_days: [] };
      const nextDateDefault = resolveNextAttendanceDateForStudent(today, studentNoDays);
      expect(nextDateDefault).toBeDefined();

      const studentWithDays: Partial<Student> = { id: 's-days', selected_days: ['monday', 'thursday'] };
      const nextDateExplicit = resolveNextAttendanceDateForStudent(today, studentWithDays);
      expect(nextDateExplicit).toBeDefined();

      // invalid base date fallback
      const fallbackInvalid = resolveNextAttendanceDateForStudent('invalid-date', null);
      expect(fallbackInvalid).toBe(today);
    });

    it('should resolveAutoDrillHomeworkText across math, english, and review/test exclusions', () => {
      expect(resolveAutoDrillHomeworkText('算数', null)).toBe('');

      // Math slot with range
      const periodsMath = {
        1: { subject: '算数', startLessonName: 'かけ算1', endLessonName: 'かけ算3', lessonRange: 'かけ算 1〜3' },
        2: { subject: '国語', startLessonName: '漢字' }
      };
      const hwMath = resolveAutoDrillHomeworkText('算数', periodsMath, '小3');
      expect(hwMath).toContain('かけ算 1 〜 3（2回目演習）');

      // Math slot where startLessonName is used without lessonRange
      const periodsMathNoRange = {
        1: { subject: '数学', startLessonName: '正負の数1', endLessonName: '正負の数2' }
      };
      const hwMathNoRange = resolveAutoDrillHomeworkText('数学', periodsMathNoRange, '中1');
      expect(hwMathNoRange).toContain('数学: 正負の数1 〜 正負の数2（2回目演習）');

      // English slot
      const periodsEnglish = {
        1: { subject: '英語', startLessonName: 'Unit1-1', endLessonName: 'Unit1-1', lessonRange: 'Unit1-1' }
      };
      const hwEng = resolveAutoDrillHomeworkText('英語', periodsEnglish, '中1');
      expect(hwEng).toBe('英語: Unit1-1（2回目演習）');

      // Exclusion of unit tests
      const periodsTests = {
        1: { subject: '英語', startLessonName: '単元確認テスト' },
        2: { subject: '英語', startLessonName: '英語確認テスト' }
      };
      expect(resolveAutoDrillHomeworkText('英語', periodsTests, '中1')).toBe('');
    });

    it('should evaluate isUnitTestCompletedForStudent across completed_lesson_ids, masters, and mini_test_results', () => {
      expect(isUnitTestCompletedForStudent(null, 'テスト')).toBe(false);
      expect(isUnitTestCompletedForStudent({ id: 's1' }, '')).toBe(false);

      // 1. Exact match in completed_lesson_ids
      const st1: Partial<Student> = { id: 's1', completed_lesson_ids: ['単元確認テスト1'] };
      expect(isUnitTestCompletedForStudent(st1, '単元確認テスト1')).toBe(true);

      // 2. Master match
      const masters = [
        { id: 'm-ut-1', item_type: 'unit_test', subject: '数学', lesson_name: '正負の数 単元テスト', unit_name: '正負の数' }
      ] as any;
      const st2: Partial<Student> = { id: 's2', completed_lesson_ids: ['m-ut-1'] };
      expect(isUnitTestCompletedForStudent(st2, '正負の数 単元テスト', '数学', masters)).toBe(true);

      // 3. Mini test result passed (score >= 80 or passed === true)
      const miniResults = [
        { id: 'mtr-1', student_id: 's3', test_content: '連立方程式 確認テスト', passed: true, score: 90, date: getDynamicDateStr(0) }
      ] as any;
      const st3: Partial<Student> = { id: 's3', completed_lesson_ids: [] };
      expect(isUnitTestCompletedForStudent(st3, '連立方程式 確認テスト', '数学', masters, miniResults)).toBe(true);

      // 4. Not completed
      expect(isUnitTestCompletedForStudent(st3, '未実施テスト', '数学', masters, miniResults)).toBe(false);
    });

    it('should sortGradeOptions naturally and handle unknown grades', () => {
      const grades = ['高2', '小3', '中1', '未知学年', '小1', '高1'];
      const sorted = sortGradeOptions(grades);
      expect(sorted[0]).toBe('小1');
      expect(sorted[1]).toBe('小3');
      expect(sorted[2]).toBe('中1');
      expect(sorted[3]).toBe('高1');
      expect(sorted[4]).toBe('高2');
      expect(sorted[5]).toBe('未知学年');
    });

    it('should inferSelectedStartGrade from current selection or master lookup', () => {
      expect(inferSelectedStartGrade('中2', 'm-1', [])).toBe('中2');
      expect(inferSelectedStartGrade(undefined, '', [])).toBe('');

      const masters = [
        { id: 'm-1', grade: '中3', unit_name: '三平方の定理', lesson_name: '三平方1' },
        { id: 'm-2', sort_order: 105, grade_level: '小5', unit_name: '割合', lesson_name: '割合1' }
      ] as any;

      expect(inferSelectedStartGrade(undefined, 'm-1', masters)).toBe('中3');
      expect(inferSelectedStartGrade(undefined, '105', masters)).toBe('5年生');
      expect(inferSelectedStartGrade(undefined, '三平方の定理', masters)).toBe('中3');
      expect(inferSelectedStartGrade(undefined, 'unknown', masters)).toBe('');
    });

    it('should calculateStudentMilestoneSeq correctly', () => {
      const units = [
        { id: 'u1', sequence_order: 1 },
        { id: 'u2', sequence_order: 2 },
        { id: 'u3', sequence_order: 3 }
      ] as any;

      // Completed tasks
      const tasksCompleted = [
        { unit_id: 'u1', status: 'completed' },
        { unit_id: 'u2', status: 'completed' }
      ] as any;
      expect(calculateStudentMilestoneSeq(tasksCompleted, units, null)).toBe(2);

      // Start unit fallback
      const studentWithStart: Partial<Student> = { id: 's1', start_unit_id: 'u3' };
      expect(calculateStudentMilestoneSeq([], units, studentWithStart)).toBe(2);

      // Default fallback
      expect(calculateStudentMilestoneSeq([], units, null)).toBe(0);
    });
  });

