  describe('TeacherDashboard: resolveAutoTestConfigForPeriod & resolveAutoTestsFromPeriods & resolveAutoDrillHomeworks', () => {
    const mockStudent: Student = {
      id: 'st-auto-test',
      name: 'テスト生徒',
      grade: '中1',
      school_id: 'sch-1',
      branch_id: 'br-1',
      completed_lesson_ids: ['completed-test-1'],
      selected_subjects: ['数学', '英語']
    } as any;

    const mockMasters: CurriculumMaster[] = [
      {
        id: 'm-ut-1',
        subject: '数学',
        grade: '中1',
        item_type: 'unit_test',
        unit_name: '正の数・負の数',
        lesson_name: '正の数・負の数 単元確認テスト'
      },
      {
        id: 'm-ut-2',
        subject: '数学',
        grade: '中1',
        item_type: 'unit_test',
        unit_name: '文字と式',
        lesson_name: '文字と式 単元確認テスト'
      },
      {
        id: 'm-ut-no-unit',
        subject: '数学',
        grade: '中1',
        item_type: 'unit_test',
        lesson_name: '方程式 単元確認テスト'
      },
      {
        id: 'm-normal-1',
        subject: '数学',
        grade: '中1',
        item_type: 'lesson',
        unit_name: '正の数・負の数',
        lesson_name: '正負の加減'
      }
    ] as any;

    it('resolveAutoTestConfigForPeriod should handle invalid slot or missing subject', () => {
      expect(resolveAutoTestConfigForPeriod(null, mockStudent)).toBeNull();
      expect(resolveAutoTestConfigForPeriod({}, mockStudent)).toBeNull();
      expect(resolveAutoTestConfigForPeriod({ subject: '' }, mockStudent)).toBeNull();
    });

    it('resolveAutoTestConfigForPeriod should return null if slot is not a unit test', () => {
      const slot = {
        subject: '数学',
        startLessonId: 'm-normal-1',
        startLessonName: '正負の加減',
        lessonRange: '正負の加減'
      };
      expect(resolveAutoTestConfigForPeriod(slot, mockStudent, mockMasters)).toBeNull();
    });

    it('resolveAutoTestConfigForPeriod should identify test via startMaster, endMaster, lesson names, or lessonRange', () => {
      // 1. startMaster item_type === 'unit_test'
      const slot1 = { subject: '数学', startLessonId: 'm-ut-1' };
      const res1 = resolveAutoTestConfigForPeriod(slot1, mockStudent, mockMasters);
      expect(res1).not.toBeNull();
      expect(res1?.content).toBe('正の数・負の数 - 正の数・負の数 単元確認テスト');
      expect(res1?.unitName).toBe('正の数・負の数');

      // 2. endMaster item_type === 'unit_test' (when startMaster has no unit_name)
      const slot2 = { subject: '数学', startLessonId: 'm-ut-no-unit', endLessonId: 'm-ut-2' };
      const res2 = resolveAutoTestConfigForPeriod(slot2, mockStudent, mockMasters);
      expect(res2).not.toBeNull();
      expect(res2?.content).toBe('文字と式 - 文字と式 単元確認テスト');

      // 3. customTheme fallback
      const slot3 = {
        subject: '数学',
        startLessonName: '確認テスト 応用編',
        customTheme: '方程式発展'
      };
      const res3 = resolveAutoTestConfigForPeriod(slot3, mockStudent, mockMasters);
      expect(res3).not.toBeNull();
      expect(res3?.content).toContain('方程式発展 -');

      // 4. endLessonName contains 単元確認テスト
      const slot4 = {
        subject: '数学',
        endLessonName: '一次関数の単元確認テスト'
      };
      const res4 = resolveAutoTestConfigForPeriod(slot4, mockStudent, []);
      expect(res4).not.toBeNull();

      // 5. lessonRange contains 単元テスト
      const slot5 = {
        subject: '数学',
        lessonRange: '図形の単元テスト'
      };
      const res5 = resolveAutoTestConfigForPeriod(slot5, mockStudent, []);
      expect(res5).not.toBeNull();
    });

    it('resolveAutoTestConfigForPeriod should return null if test is already completed', () => {
      const studentWithCompleted: Student = {
        ...mockStudent,
        completed_lesson_ids: ['正の数・負の数 - 正の数・負の数 単元確認テスト']
      };
      const slot = { subject: '数学', startLessonId: 'm-ut-1' };
      expect(resolveAutoTestConfigForPeriod(slot, studentWithCompleted, mockMasters)).toBeNull();
    });

    it('resolveAutoTestConfigForPeriod should return null if test already exists in existingTests', () => {
      const slot = { subject: '数学', startLessonId: 'm-ut-1' };
      const existing = [{ subject: '数学', content: '正の数・負の数 - 正の数・負の数 単元確認テスト' }];
      expect(resolveAutoTestConfigForPeriod(slot, mockStudent, mockMasters, existing)).toBeNull();
    });

    it('resolveAutoTestsFromPeriods should process all slots and skip duplicates', () => {
      const currentPeriods = {
        1: { subject: '数学', startLessonId: 'm-ut-1' },
        2: { subject: '数学', startLessonId: 'm-ut-1' }, // duplicate
        3: { subject: '英語', startLessonName: '単元確認テスト Lesson 1' }
      };

      const results = resolveAutoTestsFromPeriods(currentPeriods, mockStudent, mockMasters);
      expect(results.length).toBe(2);
      expect(results[0].subject).toBe('数学');
      expect(results[1].subject).toBe('英語');
    });

    it('resolveAutoTestsFromPeriods should handle array of periods or empty periods', () => {
      expect(resolveAutoTestsFromPeriods([], mockStudent, mockMasters)).toEqual([]);
      expect(resolveAutoTestsFromPeriods(null as any, mockStudent, mockMasters)).toEqual([]);

      const periodArr = [
        { subject: '数学', startLessonId: 'm-ut-1' }
      ];
      const res = resolveAutoTestsFromPeriods(periodArr, mockStudent, mockMasters);
      expect(res.length).toBe(1);
    });

    it('resolveAutoDrillHomeworks should synchronize 2nd drill homeworks for math and english', () => {
      const nextDate = getDynamicDateStr(3);
      const periods = {
        1: { subject: '数学', lessonRange: '正負の数 1 〜 5' },
        2: { subject: '英語', lessonRange: 'Unit 1 Step 1 〜 Step 3' }
      };

      // 1. Initial creation
      const res = resolveAutoDrillHomeworks(periods, '中1', nextDate, []);
      expect(res.length).toBe(2);
      expect(res.some(h => h.subject === '数学' && h.type === 'drill_2nd')).toBe(true);
      expect(res.some(h => h.subject === '英語' && h.type === 'drill_2nd')).toBe(true);

      // 2. Updating existing homework
      const existing = [
        { id: 'hw-old', subject: '数学', type: 'drill_2nd', content: '旧宿題', deadline: nextDate, targetScope: 'individual' },
        { id: 'hw-empty', content: '  ' } // should be filtered out
      ];
      const updated = resolveAutoDrillHomeworks(periods, '中1', nextDate, existing);
      const mathHw = updated.find(h => h.subject === '数学');
      expect(mathHw?.id).toBe('hw-old');
      expect(mathHw?.content).toContain('2回目演習');
      expect(updated.some(h => h.id === 'hw-empty')).toBe(false);
    });

    it('resolveAutoDrillHomeworks should handle elementary arithmetic grade normalization', () => {
      const nextDate = getDynamicDateStr(2);
      const periods = {
        1: { subject: '算数', lessonRange: 'たしざん 1 〜 3' }
      };
      const res = resolveAutoDrillHomeworks(periods, '小2', nextDate, []);
      expect(res.some(h => h.subject === '算数' && h.type === 'drill_2nd')).toBe(true);
    });
  });

