  describe('TeacherDashboard: lookupLessonById and evaluateAutoPassStatus edge branches', () => {
    it('should return null when lookupLessonById cannot find master or unit', () => {
      expect(lookupLessonById('', [], [])).toBeNull();
      expect(lookupLessonById('unknown-id-xyz', [], [])).toBeNull();
    });

    it('should find lesson by lesson_name or unit fallback in lookupLessonById', () => {
      const masters = [
        { id: 'm1', lesson_name: '単純なレッスン名', unit_name: '', sort_order: null, subject: '数学' }
      ] as any;
      const res = lookupLessonById('単純なレッスン名', masters, []);
      expect(res?.id).toBe('m1');
      expect(res?.name).toBe('単純なレッスン名');
      expect(res?.sort_order).toBe(0);

      const units = [
        { id: 'u1', name: '単元名マッチ', sequence_order: null, subject: '国語' }
      ] as any;
      const unitRes = lookupLessonById('単元名マッチ', [], units);
      expect(unitRes?.id).toBe('u1');
      expect(unitRes?.sort_order).toBe(0);
    });

    it('should evaluate evaluateAutoPassStatus across threshold syntax (% , 割, 点, and NaN)', () => {
      expect(evaluateAutoPassStatus(NaN)).toBe('unstarted');
      expect(evaluateAutoPassStatus(85, '8割')).toBe('passed');
      expect(evaluateAutoPassStatus(75, '8割')).toBe('failed');
      expect(evaluateAutoPassStatus(75, '70点')).toBe('passed');
      expect(evaluateAutoPassStatus(65, '70点')).toBe('failed');
      expect(evaluateAutoPassStatus(90, '80%')).toBe('passed');
      expect(evaluateAutoPassStatus(70, '80%')).toBe('failed');
      expect(evaluateAutoPassStatus(75, null, 'C')).toBe('passed'); // fallback to level
    });
  });

  describe('TeacherDashboard: determineActiveGradeForSubject and resolveNextAttendanceDateForStudent and isUnitCheckTestStep deep branches', () => {
    it('determineActiveGradeForSubject should find next grade when student grade is completed or fallback to student grade or 小1', () => {
      const student: Student = {
        id: 'st-grade-search',
        grade: '小3',
        completed_lesson_ids: ['m-g3-1', 'm-g3-2']
      } as any;

      const masters: CurriculumMaster[] = [
        { id: 'm-g3-1', subject: '算数', grade: '小3', sort_order: 1 },
        { id: 'm-g3-2', subject: '算数', grade: '小3', sort_order: 2 },
        { id: 'm-g4-1', subject: '算数', grade: '小4', sort_order: 3 }
      ] as any;

      // 1. All 小3 masters are completed -> finds next uncompleted in 小4
      const resultG4 = determineActiveGradeForSubject('算数', student, [], {}, undefined, masters);
      expect(resultG4).toBe('小4');

      // 2. No matching masters -> falls back to student's registered grade
      const allCompletedStudent: Student = {
        ...student,
        completed_lesson_ids: ['m-g3-1', 'm-g3-2', 'm-g4-1']
      };
      const resultFallback = determineActiveGradeForSubject('算数', allCompletedStudent, [], {}, undefined, []);
      expect(resultFallback).toBe('小3');

      // 3. Student has unrecognized grade format and no masters -> falls back to '小1'
      const unkStudent: Student = {
        id: 'st-unk',
        grade: '小???',
        completed_lesson_ids: ['m-g3-1', 'm-g3-2', 'm-g4-1']
      } as any;
      const resultDefault = determineActiveGradeForSubject('算数', unkStudent, [], {}, undefined, []);
      expect(resultDefault).toBe('小1');
    });

    it('resolveNextAttendanceDateForStudent should handle invalid dates and empty student', () => {
      const today = getDynamicDateStr(0);
      expect(resolveNextAttendanceDateForStudent(undefined, null)).toBe(today);
      expect(resolveNextAttendanceDateForStudent('invalid-date', null)).toBe(today);

      const studentNoDays: Partial<Student> = { id: 'st-nd', selected_days: [] };
      const nextDate = resolveNextAttendanceDateForStudent(today, studentNoDays);
      expect(nextDate).toBeDefined();
      expect(new Date(nextDate).getTime()).toBeGreaterThan(new Date(today).getTime());
    });

    it('isUnitCheckTestStep should handle sort_order match, review tests, and unit name unit tests', () => {
      expect(isUnitCheckTestStep('s1', [])).toBe(false);
      expect(isUnitCheckTestStep('s1', null as any)).toBe(false);

      const timeline = [
        { id: 'u1', sort_order: 10, lesson_name: 'まとめテスト 1' }, // review test -> false
        { id: 'u2', sort_order: 20, lesson_name: '第1節', unit_name: 'Check Test 章' }, // review test -> false
        { id: 'u3', sort_order: 30, lesson_name: '通常授業', unit_name: '第1章' }, // normal -> false
        { id: 'u4', sort_order: 40, lesson_name: '計算 単元確認テスト' }, // isLessonUnitTest -> true
        { id: 'u5', sort_order: 50, lesson_name: 'テスト', unit_name: '一次関数 単元テスト' }, // isLessonUnitTest unit -> true
        { id: 'u6', sort_order: 60, item_type: 'unit_test', lesson_name: '演習' } // item_type unit_test -> true
      ] as any;

      expect(isUnitCheckTestStep('non-existent', timeline)).toBe(false);
      expect(isUnitCheckTestStep('10', timeline)).toBe(false); // matches sort_order 10, review test -> false
      expect(isUnitCheckTestStep('20', timeline)).toBe(false); // review test -> false
      expect(isUnitCheckTestStep('30', timeline)).toBe(false); // normal -> false
      expect(isUnitCheckTestStep('40', timeline)).toBe(true); // matching sort_order 40, unit test -> true
      expect(isUnitCheckTestStep('u5', timeline)).toBe(true); // matching id u5, unit test -> true
      expect(isUnitCheckTestStep('u6', timeline)).toBe(true); // matching id u6, item_type unit_test -> true
    });
  });

