  describe('TeacherDashboard: resolveLessonsForSubject', () => {
    it('should resolve lessons with minimal parameters using fallback db masters', () => {
      const lessons = resolveLessonsForSubject({ subject: '数学' });
      expect(Array.isArray(lessons)).toBe(true);
      lessons.forEach(l => {
        expect(l).toHaveProperty('id');
        expect(l).toHaveProperty('name');
        expect(l).toHaveProperty('sort_order');
        expect(l).toHaveProperty('isStartUnit');
      });
    });

    it('should filter school units by selectedStudent school_id and match subject', () => {
      const schoolUnits = [
        { id: 'su-1', school_id: 'sch-1', subject: '数学', name: '一次方程式の応用', sequence_order: 10 },
        { id: 'su-2', school_id: 'sch-2', subject: '数学', name: '他校の単元', sequence_order: 20 },
        { id: 'su-3', school_id: 'sch-1', subject: '英語', name: 'be動詞', sequence_order: 5 },
        { id: 'su-4', school_id: 'sch-1', subject: '数学', name: '単元確認テスト 1', is_unit_test: true, sequence_order: 15 } // should be excluded
      ] as any;

      const lessons = resolveLessonsForSubject({
        subject: '数学',
        selectedStudent: { id: 'st-sch', school_id: 'sch-1' },
        allCurriculumUnits: schoolUnits,
        curriculumMastersList: []
      });

      const schoolUnit = lessons.find(l => l.id === 'su-1');
      expect(schoolUnit).toBeDefined();
      expect(schoolUnit?.name).toBe('一次方程式の応用');

      // Others should not be in lessons or excluded
      expect(lessons.find(l => l.id === 'su-2')).toBeUndefined();
      expect(lessons.find(l => l.id === 'su-3')).toBeUndefined();
      expect(lessons.find(l => l.id === 'su-4')).toBeUndefined();
    });

    it('should format master units properly and respect start unit id', () => {
      const masterList = [
        { id: 'm-1', subject: '数学', unit_name: '方程式', lesson_name: '1- 連立方程式の解法', sort_order: 1 },
        { id: 'm-2', subject: '数学', unit_name: '', lesson_name: '一次不等式', sort_order: 2 },
        { id: 'm-ut', subject: '数学', unit_name: '方程式', lesson_name: '方程式 単元確認テスト', sort_order: 3, item_type: 'unit_test' }
      ] as any;

      const lessons = resolveLessonsForSubject({
        subject: '数学',
        selectedStudent: { id: 'st-start', start_units: { '数学': 'm-1' } },
        curriculumMastersList: masterList,
        allCurriculumUnits: []
      });

      const m1 = lessons.find(l => l.id === 'm-1');
      expect(m1).toBeDefined();
      expect(m1?.name).toBe('方程式 - 連立方程式の解法');
      expect(m1?.isStartUnit).toBe(true);

      const m2 = lessons.find(l => l.id === 'm-2');
      expect(m2).toBeDefined();
      expect(m2?.name).toBe('一次不等式');
      expect(m2?.isStartUnit).toBe(false);

      // Unit test should be excluded
      expect(lessons.find(l => l.id === 'm-ut')).toBeUndefined();
    });

    it('should include fallback units without school_id when not already present', () => {
      const fallbackList = [
        { id: 'fb-1', subject: '英語', name: '一般動詞過去形', sequence_order: 5 },
        { id: 'fb-2', school_id: 'sch-diff', subject: '英語', name: '他校単元', sequence_order: 8 }
      ] as any;

      const lessons = resolveLessonsForSubject({
        subject: '英語',
        selectedStudent: { id: 'st-fb', school_id: 'sch-main' },
        allCurriculumUnits: fallbackList,
        curriculumMastersList: []
      });

      expect(lessons.find(l => l.id === 'fb-1')).toBeDefined();
      expect(lessons.find(l => l.id === 'fb-2')).toBeUndefined();
    });

    it('should include candidate units from periodSelections', () => {
      const periodSelections = {
        '1': {
          subject: '数学',
          startLessonId: 'custom-period-unit-1',
          startLessonName: '特別補習単元',
          endLessonId: 'custom-period-unit-2',
          endLessonName: '特別補習単元演習'
        }
      };

      const lessons = resolveLessonsForSubject({
        subject: '数学',
        periodSelections,
        allCurriculumUnits: [],
        curriculumMastersList: []
      });

      const customUnit1 = lessons.find(l => l.id === 'custom-period-unit-1');
      expect(customUnit1).toBeDefined();
      expect(customUnit1?.name).toBe('特別補習単元');

      const customUnit2 = lessons.find(l => l.id === 'custom-period-unit-2');
      expect(customUnit2).toBeDefined();
      expect(customUnit2?.name).toBe('特別補習単元演習');
    });
  });

