    it('db: clearLocalMockCache, getMockData, and getMockObject should handle non-browser and JSON parse error branches', () => {
      const origIsBrowser = (db as any).isBrowser;
      try {
        // 1. Non-browser environment simulation
        (db as any).isBrowser = () => false;
        db.clearLocalMockCache(); // Line 1117 return;

        // getMockData: first call initializes nodeMemoryStore, second call retrieves from it
        const list1 = (db as any).getMockData('node_test_list', [1, 2, 3]);
        expect(list1).toEqual([1, 2, 3]);
        const list2 = (db as any).getMockData('node_test_list', [4, 5, 6]);
        expect(list2).toEqual([1, 2, 3]); // returns cached

        // getMockObject: first call initializes nodeMemoryStore, second call retrieves from it
        const obj1 = (db as any).getMockObject('node_test_obj', { val: 'abc' });
        expect(obj1).toEqual({ val: 'abc' });
        const obj2 = (db as any).getMockObject('node_test_obj', { val: 'xyz' });
        expect(obj2).toEqual({ val: 'abc' }); // returns cached

        // 2. Browser environment JSON error handling and clear error handling
        (db as any).isBrowser = () => true;

        // JSON parse error in getMockData
        localStorage.setItem('tentoru_corrupt_data', 'INVALID_JSON_DATA');
        const fallbackList = (db as any).getMockData('corrupt_data', ['default_item']);
        expect(fallbackList).toEqual(['default_item']);

        // JSON parse error in getMockObject
        localStorage.setItem('tentoru_corrupt_obj', 'INVALID_JSON_OBJ');
        const fallbackObj = (db as any).getMockObject('corrupt_obj', { key: 'default_val' });
        expect(fallbackObj).toEqual({ key: 'default_val' });

        // Exception during clearLocalMockCache
        const origRemove = localStorage.removeItem;
        localStorage.removeItem = () => { throw new Error('Storage lock'); };
        expect(() => db.clearLocalMockCache()).not.toThrow();
        localStorage.removeItem = origRemove;
      } finally {
        (db as any).isBrowser = origIsBrowser;
      }
    });

