    it('TeacherDashboard: resolveAutoTestConfigForPeriod & resolveAutoTestsFromPeriods edge branches', () => {
      // 1. sel is null or no subject
      expect(resolveAutoTestConfigForPeriod(null, null)).toBeNull();
      expect(resolveAutoTestConfigForPeriod({ period: 1 }, null)).toBeNull();

      // 2. Not a test node
      expect(resolveAutoTestConfigForPeriod({ subject: '数学', startLessonName: '通常の授業' }, null)).toBeNull();

      // 3. Test node detected by endLessonName unit_test master
      const masters: CurriculumMaster[] = [
        { id: 'm-end-ut', item_type: 'unit_test', unit_name: '方程式', lesson_name: '確認テスト', grade: '中1', subject: '数学', sort_order: 1 }
      ];
      const selEnd = {
        subject: '数学',
        endLessonId: 'm-end-ut',
        startLessonName: '方程式 演習',
        endLessonName: '確認テスト'
      };
      const resEnd = resolveAutoTestConfigForPeriod(selEnd, { completed_lesson_ids: [] }, masters);
      expect(resEnd).not.toBeNull();
      expect(resEnd?.unitName).toBe('方程式');
      expect(resEnd?.content).toBe('方程式 - 確認テスト');

      // 4. Test node detected by customTheme and custom isCompletedFn
      const selCustom = {
        subject: '数学',
        lessonRange: '単元確認テスト',
        customTheme: '図形と計量'
      };
      const resCustom = resolveAutoTestConfigForPeriod(selCustom, null, [], [], () => false);
      expect(resCustom?.content).toBe('図形と計量 - 単元確認テスト');

      // 5. Test node where test is already completed -> returns null
      const resCompleted = resolveAutoTestConfigForPeriod(selCustom, null, [], [], () => true);
      expect(resCompleted).toBeNull();

      // 6. Test node where existingTests contains it -> returns null
      const existingTests = [{ subject: '数学', content: '図形と計量 - 単元確認テスト' }];
      const resExists = resolveAutoTestConfigForPeriod(selCustom, null, [], existingTests, () => false);
      expect(resExists).toBeNull();

      // 7. Unit name fallback to startLessonName?.split(' ')[0]
      const selSplit = {
        subject: '数学',
        startLessonName: '関数 単元テスト'
      };
      const resSplit = resolveAutoTestConfigForPeriod(selSplit, { completed_lesson_ids: [] }, []);
      expect(resSplit?.unitName).toBe('関数');

      // 8. resolveAutoTestsFromPeriods with Array vs Object
      const arrayPeriods = [selEnd, selSplit];
      const autoFromArr = resolveAutoTestsFromPeriods(arrayPeriods, { completed_lesson_ids: [] }, masters);
      expect(autoFromArr.length).toBeGreaterThan(0);

      const objPeriods = { 1: selEnd, 2: selSplit };
      const autoFromObj = resolveAutoTestsFromPeriods(objPeriods, { completed_lesson_ids: [] }, masters);
      expect(autoFromObj.length).toBeGreaterThan(0);
    });

    it('TeacherDashboard: sortGradeOptions, inferSelectedStartGrade, calculateStudentMilestoneSeq edge branches', () => {
      // 1. sortGradeOptions with unknown grades, mixed known/unknown
      const grades = ['既卒', '小6', '未知の学年B', '中2', '未知の学年A'];
      const sortedGrades = sortGradeOptions(grades);
      expect(sortedGrades[0]).toBe('小6');
      expect(sortedGrades[1]).toBe('中2');
      expect(sortedGrades[2]).toBe('既卒');
      expect(sortedGrades[3]).toBe('未知の学年A');
      expect(sortedGrades[4]).toBe('未知の学年B');

      // 2. inferSelectedStartGrade
      const masters: any[] = [
        { id: 'm-infer-1', sort_order: 10, unit_name: '一次関数', lesson_name: 'グラフ', grade: '中2' }
      ];
      // Already selected
      expect(inferSelectedStartGrade('中3', 'm-infer-1', masters)).toBe('中3');
      // No startVal
      expect(inferSelectedStartGrade('', '', masters)).toBe('');
      // Found by ID
      expect(inferSelectedStartGrade('', 'm-infer-1', masters)).toBe('中2');
      // Found by sort_order
      expect(inferSelectedStartGrade('', '10', masters)).toBe('中2');
      // Found by unit_name
      expect(inferSelectedStartGrade('', '一次関数', masters)).toBe('中2');
      // Found by lesson_name
      expect(inferSelectedStartGrade('', 'グラフ', masters)).toBe('中2');
      // Not found
      expect(inferSelectedStartGrade('', 'non-existent', masters)).toBe('');

      // 3. calculateStudentMilestoneSeq
      const units: any[] = [
        { id: 'u1', sequence_order: 3 },
        { id: 'u2', sequence_order: 5 }
      ];
      // Has completed tasks
      const tasksWithCompleted: any[] = [{ unit_id: 'u2' }];
      expect(calculateStudentMilestoneSeq(tasksWithCompleted, units)).toBe(5);

      // No completed tasks, but student has start_unit_id
      const stWithStart: any = { start_unit_id: 'u1' };
      expect(calculateStudentMilestoneSeq([], units, stWithStart)).toBe(2); // 3 - 1 = 2

      // No completed tasks, student start_unit_id not matched
      const stUnmatched: any = { start_unit_id: 'u-none' };
      expect(calculateStudentMilestoneSeq([], units, stUnmatched)).toBe(0);

      // No student at all
      expect(calculateStudentMilestoneSeq([], units, null)).toBe(0);
    });

